{
  "info": {
    "title": "UAE Webhook Template",
    "version": "v2.1-errata2",
    "description": "OpenAPI description provided **as a template** for guidance in implementing Webhooks under the UAE Open Finance Programme."
  },
  "servers": [
    {
      "url": "https://[subscription.Webhook.Url]"
    }
  ],
  "operations": {
    "/": {
      "post": {
        "operationId": "UnsignedEventNotificationPayload_SignedEventNotificationPayload",
        "parameters": [],
        "description": "This endpoint provides a template for the implementation of Webhooks at a TPP.\n\nA 202 or 204 HTTP return code with an empty payload is expected in acknowledgement of receipt.\n\nTPPs should observe the standardized error payloads as defined by the Open Finance Framework and provided in this API\ndescription.",
        "summary": "Event Notification Template",
        "responses": {
          "202": {
            "description": "Accepted",
            "headers": {
              "x-fapi-interaction-id": {
                "required": false,
                "description": "An RFC4122 UID used as a correlation ID.",
                "schema": {
                  "type": "string"
                }
              }
            }
          },
          "204": {
            "description": "No content",
            "headers": {
              "x-fapi-interaction-id": {
                "required": false,
                "description": "An RFC4122 UID used as a correlation ID.",
                "schema": {
                  "type": "string"
                }
              }
            }
          },
          "400": {
            "$ref": "#/components/responses/400Error"
          },
          "401": {
            "$ref": "#/components/responses/401Error"
          },
          "403": {
            "$ref": "#/components/responses/403Error"
          },
          "404": {
            "$ref": "#/components/responses/404Error"
          },
          "405": {
            "$ref": "#/components/responses/405Error"
          },
          "406": {
            "$ref": "#/components/responses/406Error"
          },
          "415": {
            "$ref": "#/components/responses/415Error"
          },
          "429": {
            "$ref": "#/components/responses/429Error"
          },
          "500": {
            "$ref": "#/components/responses/500Error"
          }
        },
        "tags": [
          "Webhook Template"
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/AEWebhookEventSigned"
              }
            },
            "application/jwe": {
              "schema": {
                "type": "string"
              }
            }
          },
          "description": "Please note the `application/json` Content Type is provided for processing the Event Notification payload and does not accurately reflect the format of a serialized, signed, and encrypted JSON Web Token (JWT) that will be received at the registered Webhook. The event will be a string and be received with the Content Type value `application/jwe`.\n\nThe Schema Object is provided for TPPs to understand the correct message payload definition that must be parsed from the signed and encrypted enclosed JWT received in the Event Notification.\n\nPlease refer to the Open Finance Framework documentation for guidelines on decrypting and verifying JWTs received at Webhooks."
        }
      }
    }
  }
}

